## Code Example

```javascript
function scoreSentence(sent, lang) {
  // simple placeholder: use length and keyword hits
  const keywords = {
    en: ["great","love","best"],
    es: ["genial","me encanta","mejor"],
    fr: ["super","aimé","meilleur"]
  }[lang] || [];
  let score = sent.length;
  for (const kw of keywords) {
    if (sent.toLowerCase().includes(kw)) score += 5;
  }
  return score;
}
```

